import json
W = {1:"एक",2:"दो",3:"तीन",4:"चार",5:"पाँच",6:"छह",7:"सात",8:"आठ",9:"नौ",10:"दस",11:"ग्यारह"}
def HP(n,t,en,ts): return dict(cls="कक्षा 12", subject="English (अंग्रेज़ी)", chapter=f"Prose {n}", title=t, title_en=en, title_say=ts, subject_say="अंग्रेज़ी", chapter_say=f"गद्य पाठ {W[n]}")
def HV(n,t,en,ts): return dict(cls="कक्षा 12", subject="English (अंग्रेज़ी)", chapter=f"Poem {n}", title=t, title_en=en, title_say=ts, subject_say="अंग्रेज़ी", chapter_say=f"कविता {W[n]}")
P={}
def mk(idx,meta,intro,about,story,msg,q1,q2,nxt):
    s=[dict(kind="title",say=intro),
       dict(kind="content",icon="✍️",head=about[0],points=about[1],say=about[2]),
       dict(kind="list",icon=story[0],head=story[1],points=story[2],say=story[3]),
       dict(kind="content",icon="💡",head="Message · संदेश",points=msg[0],say=msg[1]),
       dict(kind="question",icon="❓",head="अभ्यास प्रश्न 1",q=q1[0],a=q1[1],pause=4,say="अब अभ्यास प्रश्न। पहला, "+q1[2]+" ... उत्तर, "+q1[3]),
       dict(kind="question",icon="❓",head="अभ्यास प्रश्न 2",q=q2[0],a=q2[1],pause=4,say="दूसरा, "+q2[2]+" ... उत्तर, "+q2[3]),
       dict(kind="end",say=(f"शाबाश बच्चों! पाठ को किताब से अंग्रेज़ी में पढ़िए, और नए शब्द लिखिए। अगली क्लास में हम पढ़ेंगे, {nxt}। तब तक के लिए, धन्यवाद!" if nxt else "शाबाश बच्चों! रेनबो भाग दो पूरा हुआ। बोर्ड परीक्षा के लिए हर पाठ के लेखक और सार याद कीजिए। धन्यवाद!"))]
    P[idx]=(meta,s)
mk(1,HP(1,"Indian Civilization and Culture","भारतीय सभ्यता और संस्कृति · Mahatma Gandhi","इंडियन सिविलाइज़ेशन एंड कल्चर"),"रेनबो भाग दो का पहला पाठ, महात्मा गांधी के विचार, भारतीय सभ्यता और संस्कृति पर।",
 ("About · परिचय",["Writer: Mahatma Gandhi (1869–1948)","पुस्तक 'Hind Swaraj' (1909) के विचारों पर आधारित","पश्चिमी सभ्यता से तुलना"],"ये पाठ महात्मा गांधी के विचारों पर आधारित है, उनकी पुस्तक हिंद स्वराज से, जिसमें उन्होंने भारतीय और पश्चिमी सभ्यता की तुलना की।"),
 ("🇮🇳","Main Ideas · मुख्य विचार",["सभ्यता का अर्थ: इच्छाओं को कम करना, आत्म-संयम, नैतिकता","भारतीय सभ्यता: नैतिक उत्थान पर आधारित","पश्चिमी सभ्यता: भौतिक सुख, मशीनें, इच्छाओं को बढ़ाना","भारत में हल, झोपड़ी, सादा जीवन — फिर भी संतोष","पूर्वजों ने बड़े शहरों, विलासिता से बचने की सलाह दी"],"गांधी जी कहते हैं, सच्ची सभ्यता का अर्थ, अपनी इच्छाओं पर नियंत्रण, और नैतिक जीवन। भारतीय सभ्यता नैतिकता पर आधारित है, जबकि पश्चिमी सभ्यता भौतिक सुख और मशीनों पर। हमारे पूर्वजों ने जान-बूझकर सादा जीवन चुना, हल और झोपड़ी, क्योंकि सुख मन में है, वस्तुओं में नहीं।"),
 (["सादा जीवन, उच्च विचार","इच्छाओं पर नियंत्रण ही सुख","अपनी संस्कृति पर गर्व"],"संदेश, सादा जीवन, उच्च विचार। इच्छाओं पर नियंत्रण ही सच्चा सुख है।"),
 ("What, according to Gandhi, is civilization?","Mode of conduct that points to duty — self-control, morality","गांधी जी के अनुसार सभ्यता क्या है?","आचरण का वो तरीक़ा, जो कर्तव्य और आत्म-संयम की ओर ले जाए।"),("Which book contains these ideas?","Hind Swaraj","ये विचार किस पुस्तक से हैं?","हिंद स्वराज।"),"भारत इज़ माई होम")
mk(2,HP(2,"Bharat is My Home","भारत मेरा घर है · Dr. Zakir Hussain","भारत इज़ माई होम"),"आज हम भारत के तीसरे राष्ट्रपति, डॉक्टर ज़ाकिर हुसैन का भाषण पढ़ेंगे, भारत इज़ माई होम।",
 ("About · परिचय",["Dr. Zakir Hussain (1897–1969)","भारत के तीसरे राष्ट्रपति (1967–69) · शिक्षाविद्","जामिया मिल्लिया इस्लामिया के संस्थापकों में · भारत रत्न (1963)","यह राष्ट्रपति पद ग्रहण के समय का भाषण"],"डॉक्टर ज़ाकिर हुसैन, महान शिक्षाविद्, जामिया मिल्लिया इस्लामिया के संस्थापकों में से, और भारत के तीसरे राष्ट्रपति। ये पाठ, राष्ट्रपति पद ग्रहण करते समय दिया गया उनका भाषण है।"),
 ("🏠","Main Ideas · मुख्य विचार",["पूरा भारत मेरा घर है, और भारत के लोग मेरा परिवार","राष्ट्रपति पद को धर्म या जाति से नहीं जोड़ना","भारतीय संस्कृति की एकता — विविधता का सम्मान","शिक्षा: नैतिक मूल्यों से युक्त, राष्ट्र निर्माण के लिए","गांधी जी के आदर्शों पर चलना"],"ज़ाकिर हुसैन कहते हैं, पूरा भारत मेरा घर है, और यहाँ के सब लोग मेरा परिवार। वो कहते हैं, उनका राष्ट्रपति चुना जाना किसी धर्म का नहीं, बल्कि भारत की धर्मनिरपेक्षता का प्रतीक है। वो सच्ची शिक्षा, नैतिक मूल्यों, और गांधी जी के आदर्शों पर ज़ोर देते हैं।"),
 (["राष्ट्रीय एकता और धर्मनिरपेक्षता","सेवा और नैतिकता","शिक्षा से राष्ट्र निर्माण"],"संदेश, भारत की एकता, धर्मनिरपेक्षता, और नैतिक शिक्षा।"),
 ("Who delivered 'Bharat is My Home'?","Dr. Zakir Hussain","भारत इज़ माई होम भाषण किसका है?","डॉक्टर ज़ाकिर हुसैन का।"),("He was India's ___ President.","Third","वो भारत के कौन से राष्ट्रपति थे?","तीसरे।"),"अ पिंच ऑफ़ स्नफ़")
mk(3,HP(3,"A Pinch of Snuff","एक चुटकी नसवार · कहानी · Manohar Malgonkar","अ पिंच ऑफ़ स्नफ़"),"आज हम मनोहर मलगाँवकर की कहानी पढ़ेंगे, अ पिंच ऑफ़ स्नफ़, अंधविश्वास और शुभ-अशुभ की धारणाओं पर व्यंग्य।",
 ("About · परिचय",["Manohar Malgonkar (1913–2010)","भारतीय अंग्रेज़ी उपन्यासकार, सेना में रहे","उपन्यास: A Bend in the Ganges, The Princes"],"मनोहर मलगाँवकर, भारतीय अंग्रेज़ी लेखक, जो सेना में भी रहे। अ बेंड इन द गैंजेस उनका प्रसिद्ध उपन्यास है।"),
 ("🏢","Story · कहानी",["कथावाचक एक बड़ी कंपनी (कमर्शियल फ़र्म) में उच्च पद के लिए साक्षात्कार देने जाता है","साक्षात्कार से पहले, पुराने परिचित चपरासी/ज्योतिषी जैसे पात्र से शुभ-अशुभ की बातें","कहानी में 'शुभ शकुन', अंधविश्वास, और भाग्य की धारणाओं पर व्यंग्य","सफलता योग्यता से, शकुनों से नहीं"],"कहानी का कथावाचक एक नौकरी के साक्षात्कार के लिए जाता है, और रास्ते में शुभ-अशुभ के शकुनों, और अंधविश्वासों से जुड़ी घटनाएँ होती हैं। लेखक हल्के व्यंग्य से दिखाते हैं कि लोग सफलता को भाग्य और शकुनों से जोड़ते हैं, जबकि असल में योग्यता और मेहनत ही काम आती है।"),
 (["अंधविश्वास पर व्यंग्य","योग्यता और आत्मविश्वास","हास्य-व्यंग्य शैली"],"संदेश, अंधविश्वास नहीं, योग्यता और आत्मविश्वास पर भरोसा करो।"),
 ("Who wrote 'A Pinch of Snuff'?","Manohar Malgonkar","अ पिंच ऑफ़ स्नफ़ किसने लिखी?","मनोहर मलगाँवकर ने।"),("The story satirises ___?","Superstition (अंधविश्वास)","कहानी किस पर व्यंग्य करती है?","अंधविश्वास पर।"),"आई हैव अ ड्रीम")
mk(4,HP(4,"I Have a Dream","मेरा एक सपना है · भाषण · Martin Luther King Jr.","आई हैव अ ड्रीम"),"आज हम मार्टिन लूथर किंग जूनियर का विश्व प्रसिद्ध भाषण पढ़ेंगे, आई हैव अ ड्रीम।",
 ("About · परिचय",["Martin Luther King Jr. (1929–1968), अमेरिका","अश्वेतों के नागरिक अधिकार आंदोलन के नेता — गांधी जी से प्रेरित, अहिंसा","भाषण: 28 अगस्त 1963, लिंकन मेमोरियल, वॉशिंगटन","नोबेल शांति पुरस्कार (1964)"],"मार्टिन लूथर किंग जूनियर, अमेरिका में अश्वेतों के नागरिक अधिकार आंदोलन के नेता, जो गांधी जी की अहिंसा से प्रेरित थे। अट्ठाईस अगस्त उन्नीस सौ तिरसठ को वॉशिंगटन में लाखों लोगों के सामने उन्होंने ये भाषण दिया। उन्हें नोबेल शांति पुरस्कार मिला।"),
 ("✊","Main Ideas · मुख्य विचार",["लिंकन की 'मुक्ति उद्घोषणा' के 100 वर्ष बाद भी अश्वेत स्वतंत्र नहीं","भेदभाव, ग़रीबी, अन्याय","संघर्ष अहिंसक, गरिमा और अनुशासन से","सपना: बच्चे रंग से नहीं, चरित्र से पहचाने जाएँ","अश्वेत और श्वेत बच्चे भाई-बहन की तरह साथ","स्वतंत्रता की घंटी हर पहाड़ से बजे"],"किंग कहते हैं, अब्राहम लिंकन की मुक्ति उद्घोषणा के सौ साल बाद भी, अश्वेत लोग भेदभाव और ग़रीबी में जी रहे हैं। पर संघर्ष अहिंसक होना चाहिए, नफ़रत से नहीं। फिर वो अपना सपना बताते हैं, कि एक दिन उनके बच्चे, रंग से नहीं, बल्कि चरित्र से पहचाने जाएँ, और काले-गोरे बच्चे भाई-बहन की तरह साथ रहें। हर पहाड़ से आज़ादी की घंटी बजे।"),
 (["समानता और न्याय","अहिंसक संघर्ष","रंगभेद का अंत"],"संदेश, समानता, न्याय, और अहिंसा से संघर्ष।"),
 ("When was 'I Have a Dream' delivered?","28 August 1963","आई हैव अ ड्रीम भाषण कब दिया गया?","अट्ठाईस अगस्त उन्नीस सौ तिरसठ।"),("King was inspired by ___?","Mahatma Gandhi","किंग किससे प्रेरित थे?","महात्मा गांधी से।"),"आइडियाज़ दैट हैव हेल्प्ड मैनकाइंड")
mk(5,HP(5,"Ideas that have Helped Mankind","मानवता की सहायता करने वाले विचार · Bertrand Russell","आइडियाज़ दैट हैव हेल्प्ड मैनकाइंड"),"आज हम बर्ट्रेंड रसेल का निबंध पढ़ेंगे, आइडियाज़ दैट हैव हेल्प्ड मैनकाइंड।",
 ("About · परिचय",["Bertrand Russell (1872–1970), ब्रिटेन","दार्शनिक, गणितज्ञ, शांतिवादी","साहित्य का नोबेल (1950)"],"बर्ट्रेंड रसेल, ब्रिटेन के महान दार्शनिक, गणितज्ञ, और शांति के समर्थक, जिन्हें उन्नीस सौ पचास में साहित्य का नोबेल पुरस्कार मिला।"),
 ("💡","Main Ideas · मुख्य विचार",["मानव और पशु में अंतर: विचार","दो प्रकार के विचार: ज्ञान और तकनीक बढ़ाने वाले, और नैतिक-राजनीतिक","सहायक: भाषा, आग, खेती, पशुपालन, लेखन, गणित, विज्ञान","प्रकृति पर नियंत्रण की शक्ति बढ़ी","पर मनुष्य का दूसरे मनुष्य पर नियंत्रण — युद्ध, अत्याचार","समाधान: सहयोग, सहिष्णुता, मानवता"],"रसेल कहते हैं, मनुष्य को पशुओं से अलग बनाते हैं, उसके विचार। कुछ विचारों ने ज्ञान और तकनीक बढ़ाई, जैसे भाषा, आग, खेती, लेखन, गणित। इनसे मनुष्य ने प्रकृति पर नियंत्रण पाया। पर समस्या ये है कि मनुष्य, दूसरे मनुष्यों पर भी नियंत्रण चाहता है, जिससे युद्ध होते हैं। इसलिए सहयोग और सहिष्णुता के विचार सबसे ज़रूरी हैं।"),
 (["ज्ञान के साथ नैतिकता","मानवता और सहयोग","युद्ध का विरोध"],"संदेश, ज्ञान के साथ नैतिकता ज़रूरी है, वरना ज्ञान विनाश करेगा।"),
 ("Who wrote 'Ideas that have Helped Mankind'?","Bertrand Russell","आइडियाज़ दैट हैव हेल्प्ड मैनकाइंड किसने लिखा?","बर्ट्रेंड रसेल ने।"),("What distinguishes man from animals?","Ideas / thought","मनुष्य को पशुओं से क्या अलग करता है?","विचार।"),"द आर्टिस्ट")
mk(6,HP(6,"The Artist","कलाकार · कहानी · Shiga Naoya","द आर्टिस्ट"),"आज हम जापानी लेखक शिगा नाओया की कहानी पढ़ेंगे, द आर्टिस्ट, एक बालक और उसके कलात्मक शौक़ की।",
 ("About · परिचय",["Shiga Naoya (1883–1971), जापान","जापान के आधुनिक कथाकार — 'उपन्यास का देवता'","मूल शीर्षक: Seibei's Gourds"],"शिगा नाओया, जापान के प्रसिद्ध कथाकार, ये कहानी मूल रूप से सेइबेई की लौकियाँ नाम से है।"),
 ("🎨","Story · कहानी",["बारह वर्ष का सेइबेई — लौकियों (gourds) का शौक़ीन","लौकियाँ इकट्ठा करना, साफ़ करना, चमकाना — कलाकार की नज़र","पिता और शिक्षक शौक़ से नाराज़ — शिक्षक ने कक्षा में लौकी छीनी","पिता ने गुस्से में सारी लौकियाँ तोड़ दीं","शिक्षक ने लौकी चपरासी को दी, जिसने उसे ऊँचे दाम पर बेची — कीमती निकली","सेइबेई ने चित्रकारी शुरू की"],"बारह साल का सेइबेई लौकियों का शौक़ीन था, वो उन्हें इकट्ठा करता, साफ़ करता, और चमकाता। उसके पिता और शिक्षक इस शौक़ को बेकार मानते थे। एक दिन शिक्षक ने कक्षा में उसकी लौकी छीन ली, और पिता ने गुस्से में उसकी सारी लौकियाँ तोड़ दीं। पर शिक्षक की छीनी लौकी, चपरासी ने एक व्यापारी को बहुत ऊँचे दाम पर बेची, यानी वो असल में बहुत क़ीमती थी, सेइबेई की नज़र सही थी। अब सेइबेई चित्र बनाने लगा।"),
 (["बच्चों की प्रतिभा को पहचानें, दबाएँ नहीं","बड़ों की संकीर्ण सोच पर व्यंग्य","कलाकार का जन्मजात गुण"],"संदेश, बच्चों की प्रतिभा को पहचानो, दबाओ मत। बड़े लोग कभी-कभी बच्चों के गुण नहीं समझ पाते।"),
 ("What was Seibei fond of?","Gourds (लौकियाँ)","सेइबेई को किसका शौक़ था?","लौकियों का।"),("Who wrote 'The Artist'?","Shiga Naoya","द आर्टिस्ट किसने लिखी?","शिगा नाओया ने।"),"हाउ फ़्री इज़ द प्रेस")
mk(8,HP(8,"How Free is the Press","प्रेस कितना स्वतंत्र है · निबंध · Dorothy L. Sayers","हाउ फ़्री इज़ द प्रेस"),"आज हम डोरोथी एल सेयर्स का निबंध पढ़ेंगे, हाउ फ़्री इज़ द प्रेस, समाचार पत्रों की स्वतंत्रता पर।",
 ("About · परिचय",["Dorothy L. Sayers (1893–1957), इंग्लैंड","जासूसी उपन्यासकार, निबंधकार, अनुवादक (दांते)","निबंध: प्रेस की स्वतंत्रता पर व्यंग्य"],"डोरोथी एल सेयर्स, इंग्लैंड की लेखिका, जो जासूसी उपन्यासों के लिए प्रसिद्ध हैं। इस निबंध में वो प्रेस की स्वतंत्रता पर सवाल उठाती हैं।"),
 ("📰","Main Ideas · मुख्य विचार",["प्रेस की स्वतंत्रता लोकतंत्र के लिए ज़रूरी — पर क्या प्रेस सच में स्वतंत्र है?","अख़बार मालिकों और विज्ञापनदाताओं पर निर्भर","समाचार तोड़-मरोड़कर, सनसनी के लिए","पाठक को सावधानी से पढ़ना चाहिए — एक से अधिक अख़बार","पत्रकार भी मालिक की नीति से बँधे"],"लेखिका कहती हैं, लोकतंत्र में प्रेस की स्वतंत्रता ज़रूरी है, पर क्या प्रेस सच में स्वतंत्र है? अख़बार, अपने मालिकों और विज्ञापन देने वालों पर निर्भर होते हैं, इसलिए कभी-कभी समाचार तोड़-मरोड़कर, या सनसनी फैलाने के लिए छापे जाते हैं। इसलिए पाठकों को सावधान रहना चाहिए, और एक से ज़्यादा अख़बार पढ़ने चाहिए।"),
 (["जागरूक पाठक बनें","सच और झूठ में अंतर पहचानें","आज: फ़ेक न्यूज़ से सावधान"],"संदेश, जागरूक पाठक बनो, हर ख़बर पर आँख मूँदकर भरोसा मत करो। आज के समय में फ़ेक न्यूज़ से सावधान रहना, यही सीख है।"),
 ("Who wrote 'How Free is the Press'?","Dorothy L. Sayers","हाउ फ़्री इज़ द प्रेस किसने लिखा?","डोरोथी एल सेयर्स ने।"),("What should a reader do?","Read more than one newspaper, carefully","लेखिका के अनुसार पाठक को क्या करना चाहिए?","एक से ज़्यादा अख़बार सावधानी से पढ़ने चाहिए।"),"इंडिया थ्रू अ ट्रैवलर्स आइज़")
mk(10,HP(10,"India Through a Traveller's Eyes","एक यात्री की नज़र में भारत · Pearl S. Buck","इंडिया थ्रू अ ट्रैवलर्स आइज़"),"आज हम अमेरिकी लेखिका पर्ल एस बक का संस्मरण पढ़ेंगे, इंडिया थ्रू अ ट्रैवलर्स आइज़।",
 ("About · परिचय",["Pearl S. Buck (1892–1973), अमेरिका","चीन में पली-बढ़ीं · उपन्यास: The Good Earth","साहित्य का नोबेल (1938)"],"पर्ल एस बक, अमेरिकी लेखिका, जो चीन में पली-बढ़ीं, उनका उपन्यास द गुड अर्थ प्रसिद्ध है, और उन्हें साहित्य का नोबेल मिला।"),
 ("✈️","Main Ideas · मुख्य विचार",["लेखिका की भारत यात्रा — भारतीय लोगों का अतिथि सत्कार","भारतीय नारियाँ — शिक्षित, आत्मविश्वासी, सुंदर","महानगरों और गाँवों का अंतर","भारतीय लोग: सरल, ईमानदार, दार्शनिक","भारत — विविधता में एकता"],"लेखिका ने भारत की यात्रा की, और यहाँ के लोगों के अतिथि सत्कार से बहुत प्रभावित हुईं। उन्होंने भारतीय नारियों की शिक्षा, आत्मविश्वास, और गरिमा की प्रशंसा की। उन्हें भारत की विविधता में एकता दिखी।"),
 (["भारत की सकारात्मक छवि","अतिथि देवो भव","विदेशी दृष्टि से अपने देश को देखना"],"संदेश, अतिथि देवो भव, भारत का अतिथि सत्कार दुनिया भर में प्रसिद्ध है।"),
 ("Who wrote 'India Through a Traveller's Eyes'?","Pearl S. Buck","इंडिया थ्रू अ ट्रैवलर्स आइज़ किसने लिखा?","पर्ल एस बक ने।"),("Her famous novel?","The Good Earth","पर्ल एस बक का प्रसिद्ध उपन्यास?","द गुड अर्थ।"),"अ मैरिज प्रपोज़ल")
mk(11,HP(11,"A Marriage Proposal","विवाह का प्रस्ताव · एकांकी नाटक · Anton Chekhov","अ मैरिज प्रपोज़ल"),"आज गद्य खंड का अंतिम पाठ, रूसी लेखक एंटन चेखव का हास्य एकांकी, अ मैरिज प्रपोज़ल।",
 ("About · परिचय",["Anton Chekhov (1860–1904), रूस","डॉक्टर और महान कहानीकार, नाटककार","हास्य एकांकी (farce) — 1888-89"],"एंटन चेखव, रूस के महान कहानीकार और नाटककार, जो पेशे से डॉक्टर थे। ये एक हास्य एकांकी है।"),
 ("💍","Story · कहानी",["पात्र: लोमोव (32 वर्ष, बीमार-सा, घबराया), चुबुकोव (ज़मींदार), नतालिया (चुबुकोव की बेटी, 25)","लोमोव नतालिया से विवाह का प्रस्ताव देने आता है","पर बात 'ऑक्सन मेडोज़' (बैलों का चरागाह) के स्वामित्व पर झगड़े में बदल जाती है","फिर कुत्तों — 'गेस' बनाम 'स्क्वीज़र' — पर झगड़ा","अंत में चुबुकोव जल्दी से दोनों का हाथ मिलाकर विवाह तय कर देता है, पर झगड़ा जारी"],"लोमोव, एक घबराया हुआ ज़मींदार, अपने पड़ोसी चुबुकोव की बेटी नतालिया से विवाह का प्रस्ताव देने आता है। पर प्रस्ताव से पहले ही, बैलों के चरागाह, ऑक्सन मेडोज़, किसका है, इस पर दोनों में झगड़ा हो जाता है। फिर किसका कुत्ता अच्छा है, इस पर झगड़ा। लोमोव बार-बार दिल की धड़कन से परेशान होता है। अंत में चुबुकोव जल्दी से दोनों के हाथ मिलाकर विवाह तय कर देता है, और झगड़ा फिर भी चलता रहता है।"),
 (["छोटी बातों पर झगड़ा — मानव स्वभाव पर हास्य","ज़मींदारों के अहंकार पर व्यंग्य","विवाह को सौदे की तरह देखना"],"संदेश, छोटी-छोटी बातों पर अहंकार में झगड़ना, मानव स्वभाव की कमज़ोरी है, चेखव ने इस पर हास्य से व्यंग्य किया।"),
 ("What did Lomov and Natalya first quarrel about?","Oxen Meadows","लोमोव और नतालिया पहले किस बात पर झगड़े?","ऑक्सन मेडोज़, यानी बैलों के चरागाह पर।"),("Who wrote 'A Marriage Proposal'?","Anton Chekhov","अ मैरिज प्रपोज़ल किसने लिखा?","एंटन चेखव ने।"),"स्वीटेस्ट लव, आई डू नॉट गो")
for n,(m,s) in P.items():
    open(f"/home/claude/videos/c12_eng_ch{n}.py","w").write(f"# auto\nMETA = {json.dumps(m, ensure_ascii=False)}\nS = {json.dumps(s, ensure_ascii=False, indent=0)}\n")
